import{_ as d,a0 as n,w as o,s as p,I as i,x as e,a1 as t,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"命令別名：保護和服務 | LCTT x X-CMD","titleTemplate":false,"description":"命令別名：保護和服務 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令別名：保護和服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令別名：保護和服務 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20190107 Aliases- To Protect and Serve","title":"命令別名：保護和服務","tag":"201905","desc":""},"relativePath":"201905/20190107 Aliases- To Protect and Serve.md","filePath":"[post].md"}'),c={name:"201905/20190107 Aliases- To Protect and Serve.md"};function h(g,s,k,b,u,f){const a=n("Link");return o(),p("div",null,[s[18]||(s[18]=i("h1",{id:"命令別名-保護和服務",tabindex:"-1"},[e("命令別名：保護和服務 "),i("a",{class:"header-anchor",href:"#命令別名-保護和服務","aria-label":"Permalink to “命令別名：保護和服務”"},"​")],-1)),s[19]||(s[19]=i("blockquote",null,[i("p",null,"Linux shell 允許你將命令彼此鏈接在一起，一次觸發執行復雜的操作，並且可以對此創建別名作為快捷方式。")],-1)),s[20]||(s[20]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/prairie-path_1920.jpg?itok=wRARsM7p",alt:""})],-1)),i("p",null,[s[1]||(s[1]=e("讓我們將繼續我們的別名系列。到目前為止，你可能已經閲讀了我們的",-1)),t(a,{href:"https://linux.cn/article-10377-1.html"},{default:l(()=>[...s[0]||(s[0]=[e("關於別名的第一篇文章",-1)])]),_:1}),s[2]||(s[2]=e("，並且應該非常清楚它們是如何為你省去很多麻煩的最簡單方法。例如，你已經看到它們幫助我們減少了輸入，讓我們看看別名派上用場的其他幾個案例。",-1))]),s[21]||(s[21]=r(`<h3 id="別名即快捷方式" tabindex="-1">別名即快捷方式 <a class="header-anchor" href="#別名即快捷方式" aria-label="Permalink to “別名即快捷方式”">​</a></h3><p>Linux shell 最美妙的事情之一是可以使用數以萬計的選項和把命令連接在一起執行真正複雜的操作。好吧，也許這種美麗是在旁觀者的眼中的，但是我們覺得這個功能很實用。</p><p>不利的一面是，你經常需要記得難以記憶或難以打字出來的命令組合。比如説硬盤上的空間非常寶貴，而你想要做一些清潔工作。你的第一步可能是尋找隱藏在你的家目錄裏的東西。你可以用來判斷的一個標準是查找不再使用的內容。<code>ls</code> 可以幫助你：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -lct</span></span></code></pre></div><p>上面的命令顯示了每個文件和目錄的詳細信息（<code>-l</code>），並顯示了每一項上次訪問的時間（<code>-c</code>），然後它按從最近訪問到最少訪問的順序排序這個列表（<code>-t</code>）。</p><p>這難以記住嗎？你可能不會每天都使用 <code>-c</code> 和 <code>-t</code> 選項，所以也許是吧。無論如何，定義一個別名，如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias lt=&#39;ls -lct&#39;</span></span></code></pre></div><p>會更容易一些。</p><p>然後，你也可能希望列表首先顯示最舊的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias lo=&#39;lt -F | tac&#39;</span></span></code></pre></div><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig01_0.png?itok=crqTm_va" alt="aliases" title="aliases"></p><p><em>圖 1：使用 lt 和 lo 別名。</em></p><p>這裏有一些有趣的事情。首先，我們使用別名（<code>lt</code>）來創建另一個別名 —— 這是完全可以的。其次，我們將一個新參數傳遞給 <code>lt</code>（後者又通過 <code>lt</code> 別名的定義傳遞給了 <code>ls</code>）。</p><p><code>-F</code> 選項會將特殊符號附加到項目的名稱後，以便更好地區分常規文件（沒有符號）和可執行文件（附加了 <code>*</code>）、目錄文件（以 <code>/</code> 結尾），以及所有鏈接文件、符號鏈接文件（以 <code>@</code> 符號結尾）等等。<code>-F</code> 選項是當你迴歸到單色終端的日子裏，沒有其他方法可以輕鬆看到列表項之間的差異時用的。在這裏使用它是因為當你將輸出從 <code>lt</code> 傳遞到 <code>tac</code> 時，你會丟失 <code>ls</code> 的顏色。</p><p>第三件我們需要注意的事情是我們使用了管道。管道用於你將一個命令的輸出傳遞給另外一個命令時。第二個命令可以使用這些輸出作為它的輸入。在包括 Bash 在內的許多 shell 裏，你可以使用管道符（<code>|</code>） 來做傳遞。</p><p>在這裏，你將來自 <code>lt -F</code> 的輸出導給 <code>tac</code>。<code>tac</code> 這個命令有點玩笑的意思，你或許聽説過 <code>cat</code> 命令，它名義上用於將文件彼此連接（con<code>cat</code>），而在實踐中，它被用於將一個文件的內容打印到終端。<code>tac</code> 做的事情一樣，但是它是以逆序將接收到的內容輸出出來。明白了嗎？<code>cat</code> 和 <code>tac</code>，技術人有時候也挺有趣的。</p><p><code>cat</code> 和 <code>tac</code> 都能輸出通過管道傳遞過來的內容，在這裏，也就是一個按時間順序排序的文件列表。</p><p>那麼，在有些離題之後，最終我們得到的就是這個列表將當前目錄中的文件和目錄以新鮮度的逆序列出（即老的在前）。</p><p>最後你需要注意的是，當在當前目錄或任何目錄運行 <code>lt</code> 時：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 這可以工作：</span></span>
<span class="line"><span>lt</span></span>
<span class="line"><span># 這也可以：</span></span>
<span class="line"><span>lt /some/other/directory</span></span></code></pre></div><p>……而 <code>lo</code> 只能在當前目錄奏效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 這可工作：</span></span>
<span class="line"><span>lo</span></span>
<span class="line"><span># 而這不行：</span></span>
<span class="line"><span>lo /some/other/directory</span></span></code></pre></div><p>這是因為 Bash 會展開別名的組分。當你鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lt /some/other/directory</span></span></code></pre></div><p>Bash 實際上運行的是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -lct /some/other/directory</span></span></code></pre></div><p>這是一個有效的 Bash 命令。</p><p>而當你鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lo /some/other/directory</span></span></code></pre></div><p>Bash 試圖運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -lct -F | tac /some/other/directory</span></span></code></pre></div><p>這不是一個有效的命令，主要是因為 <code>/some/other/directory</code> 是個目錄，而 <code>cat</code> 和 <code>tac</code> 不能用於目錄。</p><h3 id="更多的別名快捷方式" tabindex="-1">更多的別名快捷方式 <a class="header-anchor" href="#更多的別名快捷方式" aria-label="Permalink to “更多的別名快捷方式”">​</a></h3><ul><li><code>alias lll=&#39;ls -R&#39;</code> 會打印出目錄的內容，並深入到子目錄裏面打印子目錄的內容，以及子目錄的子目錄，等等。這是一個查看一個目錄下所有內容的方式。</li><li><code>mkdir=&#39;mkdir -pv&#39;</code> 可以讓你一次性創建目錄下的目錄。按照 <code>mkdir</code> 的基本形式，要創建一個包含子目錄的目錄，你必須這樣：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir newdir</span></span>
<span class="line"><span>mkdir newdir/subdir</span></span></code></pre></div><p>或這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p newdir/subdir</span></span></code></pre></div><p>而用這個別名你將只需要這樣就行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir newdir/subdir</span></span></code></pre></div><p>你的新 <code>mkdir</code> 也會告訴你創建子目錄時都做了什麼。</p><h3 id="別名也是一種保護" tabindex="-1">別名也是一種保護 <a class="header-anchor" href="#別名也是一種保護" aria-label="Permalink to “別名也是一種保護”">​</a></h3><p>別名的另一個好處是它可以作為防止你意外地刪除或覆寫已有的文件的保護措施。你可能聽説過這個 Linux 新用户的傳言，當他們以 root 身份運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -rf /</span></span></code></pre></div><p>整個系統就爆了。而決定輸入如下命令的用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -rf /some/directory/ *</span></span></code></pre></div><p>就很好地幹掉了他們的家目錄的全部內容。這裏不小心鍵入的目錄和 <code>*</code> 之間的那個空格有時候很容易就會被忽視掉。</p><p>這兩種情況我們都可以通過 <code>alias rm=&#39;rm -i&#39;</code> 別名來避免。<code>-i</code> 選項會使 <code>rm</code> 詢問用户是否真的要做這個操作，在你對你的文件系統做出不可彌補的損失之前給你第二次機會。</p><p>對於 <code>cp</code> 也是一樣，它能夠覆蓋一個文件而不會給你任何提示。創建一個類似 <code>alias cp=&#39;cp -i&#39;</code> 來保持安全吧。</p><h3 id="下一次" tabindex="-1">下一次 <a class="header-anchor" href="#下一次" aria-label="Permalink to “下一次”">​</a></h3><p>我們越來越深入到了腳本領域，下一次，我們將沿着這個方向，看看如何在命令列組合命令以給你真正的樂趣，並可靠地解決系統管理員每天面臨的問題。</p><hr>`,51)),i("p",null,[s[4]||(s[4]=e("via: ",-1)),t(a,{href:"https://www.linux.com/blog/learn/2019/1/aliases-protect-and-serve"},{default:l(()=>[...s[3]||(s[3]=[e("https://www.linux.com/blog/learn/2019/1/aliases-protect-and-serve",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=e("作者：",-1)),t(a,{href:"https://www.linux.com/users/bro66"},{default:l(()=>[...s[5]||(s[5]=[e("Paul Brown",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const x=d(c,[["render",h]]);export{C as __pageData,x as default};
